public class GossipNodeState {
    private final String nodeId;
    private final long heartbeatSequence;
    private final Map<String, String> applicationMetadata;

    public GossipNodeState(String nodeId, long heartbeatSequence) {
        this.nodeId = nodeId;
        this.heartbeatSequence = heartbeatSequence;
        this.applicationMetadata = new ConcurrentHashMap<>();
    }

    public synchronized void merge(GossipNodeState remoteState) {
        if (remoteState.getHeartbeatSequence() > this.heartbeatSequence) {
            this.heartbeatSequence = remoteState.getHeartbeatSequence();
            this.applicationMetadata.putAll(remoteState.getApplicationMetadata());
        }
    }

    public long getHeartbeatSequence() { return heartbeatSequence; }
    public Map<String, String> getApplicationMetadata() { return applicationMetadata; }
}
